mapper.sql:
FROM hrm_person p
LEFT JOIN hrm_org_dept d ON d.dept_cd = p.dept_cd
    AND d.reorg_key = #{query.reorgKey} AND d.use_yn = 'Y'
LEFT JOIN com_code grade ON grade.code = p.grade_code AND grade.parent_code = '102' AND grade.use_yn = 'Y'
LEFT JOIN com_code position ON position.code = p.position_code AND position.parent_code = '103' AND position.use_yn = 'Y'
LEFT JOIN com_code status ON status.code = p.service_status_code AND status.parent_code = '101' AND status.use_yn = 'Y'

    AND p.person_key = #{query.personKey}
    AND STRPOS(LOWER(p.name_ko), LOWER(#{query.nameKo})) > 0
    AND STRPOS(LOWER(p.employee_no), LOWER(#{query.employeeNo})) > 0
    AND STRPOS(LOWER(d.dept_nm), LOWER(#{query.deptName})) > 0
    AND d.dept_cd = #{query.deptCd}
    AND p.grade_code = #{query.gradeCode}
    AND p.position_code = #{query.positionCode}
    AND p.service_status_code = #{query.serviceStatusCode}
